9.2 Create a versioned board
We enable versioning so the board retains both writes. We use RDS, an R format that preserves the column types. The board lives inside our local workshop outputs.

box::use(
  pins[board_folder, pin_exists, pin_meta, pin_read, pin_versions,
       pin_write],
  utils[read.csv, write.csv]
)

workshop_dir &lt;- file.path("outputs", "health-wellbeing")
data_board &lt;- board_folder(
  file.path(workshop_dir, "data_store"),
  versioned = TRUE
)
pin_name &lt;- "health_wellbeing"
versions_file &lt;- file.path(workshop_dir, "dataset-versions.csv")
selection_file &lt;- file.path(workshop_dir, "analysis-data-version.txt")

write_dataset_version &lt;- function(board, name, data, description, metadata) {
  previous_versions &lt;- character()
  if (pin_exists(board, name)) {
    previous_versions &lt;- pin_versions(board, name)$version
    for (version in previous_versions) {
      if (identical(pin_meta(board, name, version = version)$user, metadata) &&
          identical(pin_read(board, name, version = version), data)) {
        return(version)
      }
    }
  }

  pin_write(
    board,
    data,
    name = name,
    type = "rds",
    title = "HealthWellbeing",
    description = description,
    metadata = metadata
  )
  new_version &lt;- setdiff(pin_versions(board, name)$version, previous_versions)
  stopifnot(length(new_version) == 1L)
  new_version
}
